; ==============================================================================================
; BIOS ПЕОМ «Практик», версія 2.16-17 (2.16-17_my/pr_bios.rom, 16 КБ, CRC32 187319F5)
; Дизасембльовано й прокоментовано автоматично, ключові місця перевірено вручну.
; Формат рядка: СЕГМЕНТ:ЗМІЩЕННЯ  байти  команда  ; коментар
; Образ ПЗП: фіз. FC000-FFFFF (дзеркало F4000-F7FFF).
;   Перші 8 КБ показано як сегмент F400 (емулятор периферії через NMI, INT 0Fh, шрифт 80-FFh).
;   Другі 8 КБ показано як F000:E000-FFFF (основний BIOS, точки входу IBM PC/XT).
; Позначка «ймовірно» означає гіпотезу, виведену з коду, а не з документації.
; Повідомлення на екрані наведено мовою оригіналу (російською, CP866) з українським перекладом.
; ==============================================================================================
;
; ВАЖЛИВО. Роз'єм живлення материнської плати «Практика» схожий на стандартний роз'єм живлення
;   5-дюймових дисководів IBM PC, АЛЕ(!) розпіновка в нього не відповідає стандартній. Якщо підключити
;   стандартний блок живлення IBM PC, мікросхеми на материнській платі згорять.
;   Перевірте розпіновку перед подачею живлення.
;
; ==============================================================================================
;
; ## Як улаштовано цей BIOS
;
; У ПЕОМ «Практик» немає частини стандартних мікросхем IBM PC: немає контролера переривань 8259 (КР580ВН59) і контролера ПДП 8237 (КР1810ВТ37). Решта мікросхем — 8255 (КР580ВВ55А), 8253 (КР580ВИ53), 6845 (КМ1809ВГ6), 765 (КР1810ВГ72А) і два 8250 (прямого радянського аналога немає) — є, але вони стоять не на стандартних портах, а у вікні пам'яті F000:0000–0FFF. Коли програма звертається до стандартного порту IBM PC, схема машини перехоплює це звернення й викликає NMI. Обробник NMI у ПЗП з'ясовує, до якого порту було звернення, і виконує його програмно: переадресовує до справжньої мікросхеми, перераховує значення або повністю підміняє пристрій. Тому звичайні програми для IBM PC працюють, хоча апаратура в машини інша.
;
; BIOS складається з двох половин по 8 КБ:
; - **Перша половина (сегмент F400)** — емулятор периферії. Обробник NMI з таблицею портів, спільний обробник апаратних переривань INT 0Fh, обробники портів, програмна передача даних дисковода, друга половина шрифту (символи 80–FFh).
; - **Друга половина (F000:E000–FFFF)** — звичайний BIOS з точками входу точно за адресами IBM PC/XT: POST, INT 09h–1Ah, завантаження, шрифт символів 00–7Fh.
;
; Процесор бачить ПЗП двічі: за адресами FC000–FFFFF і в дзеркалі F4000–F7FFF. Через дзеркало основний BIOS викликає код першої половини близькими викликами (наприклад, `call beep` за адресою F000:4C2D). Вектор INT 1Fh = F000:5C00 теж указує через дзеркало на другу половину шрифту.
;
; ## Карта регістрів апаратури (F000:0000–0FFF)
;
; | Адреса | Пристрій | Призначення |
; |---|---|---|
; | F000:0000 / 0002 | CRTC 6845 | Індексний регістр і регістр даних. INT 10h AH=0 пише в них напряму. |
; | F000:0001 / 0003 / 0005 / 0007 | 8255 | Порт A (скан-код), порт B (аналог 61h, біт 6 інвертовано), порт C (стрічка, OUT2), керувальне слово (99h). |
; | F000:0009 | — | Читається перед INT 08h. Ймовірно, скидає запит переривання від таймера. |
; | F000:0200 | Клямка NMI / запити IRQ; відеорежим | Читання — біти 0–9: номер порту; біт 10: 1 = OUT; біт 11: NMI від порту; біти 12–15: IRQ від COM1, клавіатури, таймера, дисковода. Запис слова задає відеорежим: молодший байт — колір (як 3D9), старший — режим (як 3D8). |
; | F000:0400 / 0401 | Дані OUT | Байт, записаний перехопленою командою OUT: 0400 для парного порту, 0401 для непарного. Читання 0400 підтверджує NMI. |
; | F000:0600 / 0601 / 0602 | FDC 765 | 0600 — MSR, 0602 — дані. 0601 — аналог DOR (копія в 0040:00B9): біти 0–1 — вибір дисковода, біт 2 — /RESET, біт 3 — дозвіл IRQ, біти 4–7 — двигуни. |
; | F000:0800 / 0808 | Дисковод | Цикл DACK для обміну байтом з 765 без ПДП; 0808 — те саме з сигналом TC (останній байт). Перед кожним байтом процесор виконує WAIT: ймовірно, DRQ заведено на вивід TEST. |
; | F000:0A00–0A06 (парні) | 8253 | Канали 0–2 і керувальне слово. Частота близько 1 МГц, тому емулятор перераховує дільники. |
; | F000:0A01 | LPT | Запис — дані принтера, читання — лінії стану. |
; | F000:0DF0–0DFE | 8250 COM2 | Регістри 2F8–2FF, крок 2. |
; | F000:0E10–0E1E | 8250 COM1 | Регістри 3F8–3FF, крок 2. |
;
; ## Порти, які перехоплює NMI
;
; | Порти | Що емулюється |
; |---|---|
; | 004, 005, 00B, 081 | ПДП 8237, канал 2. Адреса, лічильник, режим і сторінка запам'ятовуються в області даних 0040:009E–00B3 і використовуються під час програмної передачі даних дисковода. |
; | 020 | 8259. Розпізнається лише EOI, він знімає біт 5 порту B 8255. |
; | 040–043 | 8253, з перерахунком дільників під частоту близько 1 МГц. |
; | 060–063 | 8255, пряма переадресація (з інверсією біта 6 порту 61h). |
; | 201 | Ігровий порт. Аналоговий джойстик імітується цифровим. |
; | 2F8–2FF, 3F8–3FF | COM2 і COM1, переадресація на справжні 8250. |
; | 378–37A | LPT1. |
; | 3D4, 3D5, 3D8, 3D9, 3DA | CGA. Записи в регістри 6845 фільтруються, регістр режиму 3D8 перезавантажує R0–R9 з власних таблиць. |
; | 3F2, 3F4, 3F5 | Дисковод. Дані секторів передаються програмно, без ПДП. |
; | решта | Обробник «немає пристрою»: OUT ігнорується, IN повертає FFh. |
;
; ## Відмінності від IBM PC/XT
;
; - **Переривання.** Замість 8259 — одна лінія запиту й вектор INT 0Fh. Обробник F400:0400 читає біти 12–15 регістра F000:0200 і викликає INT 0Eh, 08h, 09h або 0Ch. Обробники INT 08h і 09h не надсилають EOI.
; - **Клавіатура.** Біт 2 байта 0040:0018 — перемикач РУС/ЛАТ (код E0 9Dh, відпускання правого Ctrl). Є таблиці ЙЦУКЕН у кодуванні CP866 і CapsLock для кирилиці.
; - **Дисководи.** Приводи 80-доріжкові. Біти 4–5 байта 0040:003E позначають диск на 720 КБ. Для дисків на 360 КБ вмикається подвійний крок. Ознаку ставить INT 19h за BPB завантажувального сектора.
; - **Відео.** Монохромного режиму немає: відеопам'ять завжди за адресою B800, контролер завжди 3D4. Регістри синхронізації 6845 (R0–R8) захищено від запису програмами. Запис R9=1 у режимі 80×25 вмикає графічний режим 160×100. Стан 3DA фіктивний: біти зворотного ходу перемикаються під час кожного читання.
; - **Шрифт.** Символи 80–FFh у CP866, але F2h–FBh замінено: заокруглені кути рамок, стрілки, знаки ÷ і ±.
; - **INT 18h.** Замість ROM BASIC — завантажувач програм з магнітофона: введення імені й пошук заголовка на стрічці. INT 15h повторює алгоритм роботи з магнітофоном IBM PC.
; - **POST.** Тест пам'яті виводить «NNN Кб проверено» («NNN КБ перевірено»). Повідомлення про помилки російською. Контрольна сума рахується по 8 КБ основного ПЗП.
;
; ## Як читати лістинг
;
; Кожен рядок містить адресу (сегмент:зміщення), байти, команду й коментар. Перед процедурами стоять заголовки з призначенням, вхідними й вихідними регістрами. Мітки `sub_XXXX` — підпрограми, `loc_XXXX` — точки переходу, `dat_XXXX` — дані, на які посилається код. Праворуч від мітки перелічено адреси, звідки на неї посилаються. Слово «ймовірно» означає висновок із коду, не підтверджений документацією. Повідомлення на екрані наведено мовою оригіналу (російською) з українським перекладом.
;
; ## Джерела
;
; - Файли BIOS узято з публікації «Журнал восстановления Практика» («Журнал відновлення Практика») на сайті zxdesu, 2016: https://zxdesu.byethost32.com/2016/07/28/%d0%b6%d1%83%d1%80%d0%bd%d0%b0%d0%bb-%d0%b2%d0%be%d1%81%d1%81%d1%82%d0%b0%d0%bd%d0%be%d0%b2%d0%bb%d0%b5%d0%bd%d0%b8%d1%8f-%d0%bf%d1%80%d0%b0%d0%ba%d1%82%d0%b8%d0%ba%d0%b0/
; - Опис комп'ютера «Практик» (ПК8641) на сайті retro-computer.ru: https://retro-computer.ru/item/PRAKTIK-PK8641.html


; ##############################################################################################
; СЕГМЕНТ F400 — перші 8 КБ ПЗП (фіз. F4000-F5FFF, те саме, що FC000-FDFFF / F000:C000-DFFF)
; ##############################################################################################

; ----------------------------------------------------------------------------------------------
; port_index_table — таблиця перетворення номера порту (000–3FF) на зміщення в таблиці обробників NMI.
; Індекс = біти 0–9 клямки F000:0200; байт = 2*номер обробника в nmi_port_handlers (F400:049F).
; Значення 52h (обробник №41 nmi_port_unused) — порт не емулюється: запис ігнорується, читання дає FFh.
; NMI_HANDLER читає звідси слово cs:[bx] і обнуляє старший байт, тобто використовується лише цей байт.
; ----------------------------------------------------------------------------------------------
port_index_table:
F400:0000  52              db     4 dup (52h)                 ; Порти 000–003 (DMA 8237: адреса/лічильник каналів 0–1) — не емулюються
F400:0004  0A              db     0Ah                         ; Порт 004 (8237: адреса каналу 2) → nmi_port_004, обробник №5
F400:0005  0C              db     0Ch                         ; Порт 005 (8237: лічильник каналу 2) → nmi_port_005, обробник №6
F400:0006  52              db     5 dup (52h)                 ; Порти 006–00A (8237: канали 3, команда, запит, маска) — не емулюються
F400:000B  0E              db     0Eh                         ; Порт 00B (8237: регістр режиму) → nmi_port_00B, обробник №7
F400:000C  52              db     20 dup (52h)                ; Порти 00C–01F (скидання тригера 8237, загальне скидання тощо) — не емулюються
F400:0020  50              db     50h                         ; Порт 020 (8259: команди OCW, зокрема EOI) → nmi_port_020, обробник №40
F400:0021  52              db     31 dup (52h)                ; Порти 021–03F (маска 8259 IMR тощо) — не емулюються (читання дає FFh)
F400:0040  10              db     10h                         ; Порт 040 (8253: лічильник каналу 0, системний таймер) → nmi_port_040, №8
F400:0041  12              db     12h                         ; Порт 041 (8253: лічильник каналу 1, регенерація ОЗП) → nmi_port_041, №9
F400:0042  14              db     14h                         ; Порт 042 (8253: лічильник каналу 2, динамік) → nmi_port_042, №10
F400:0043  16              db     16h                         ; Порт 043 (8253: регістр керівного слова) → nmi_port_043, №11
F400:0044  52              db     28 dup (52h)                ; Порти 044–05F — не емулюються
F400:0060  18              db     18h                         ; Порт 060 (8255 порт A: скан-код клавіатури) → nmi_port_060, №12
F400:0061  1A              db     1Ah                         ; Порт 061 (8255 порт B: динамік, керування клавіатурою) → nmi_port_061, №13
F400:0062  1C              db     1Ch                         ; Порт 062 (8255 порт C: перемикачі/стан) → nmi_port_062, №14
F400:0063  1E              db     1Eh                         ; Порт 063 (8255 керівне слово) → nmi_port_063, №15
F400:0064  52              db     29 dup (52h)                ; Порти 064–080 — не емулюються (зокрема сторінки DMA 080, 082–083)
F400:0081  20              db     20h                         ; Порт 081 (регістр сторінки DMA каналу 2) → nmi_port_081, №16
F400:0082  52              db     383 dup (52h)               ; Порти 082–200 — не емулюються
F400:0201  22              db     22h                         ; Порт 201 (ігровий адаптер/джойстик) → nmi_port_201, №17
F400:0202  52              db     246 dup (52h)               ; Порти 202–2F7 — не емулюються
F400:02F8  24              db     24h                         ; Порт 2F8 (COM2 8250: RBR/THR або DLL) → nmi_port_2F8, №18
F400:02F9  26              db     26h                         ; Порт 2F9 (COM2 8250: IER або DLM) → nmi_port_2F9, №19
F400:02FA  28              db     28h                         ; Порт 2FA (COM2 8250: IIR) → nmi_port_2FA, №20
F400:02FB  2A              db     2Ah                         ; Порт 2FB (COM2 8250: LCR) → nmi_port_2FB, №21
F400:02FC  2C              db     2Ch                         ; Порт 2FC (COM2 8250: MCR) → nmi_port_2FC, №22
F400:02FD  2E              db     2Eh                         ; Порт 2FD (COM2 8250: LSR) → nmi_port_2FD, №23
F400:02FE  30              db     30h                         ; Порт 2FE (COM2 8250: MSR) → nmi_port_2FE, №24
F400:02FF  32              db     32h                         ; Порт 2FF (COM2 8250: SCR) → nmi_port_2FF, №25
F400:0300  52              db     120 dup (52h)               ; Порти 300–377 — не емулюються
F400:0378  34              db     34h                         ; Порт 378 (LPT1: регістр даних) → nmi_port_378, №26
F400:0379  36              db     36h                         ; Порт 379 (LPT1: регістр стану) → nmi_port_379, №27
F400:037A  38              db     38h                         ; Порт 37A (LPT1: регістр керування) → nmi_port_37A, №28
F400:037B  52              db     89 dup (52h)                ; Порти 37B–3D3 (зокрема MDA 3B0–3BF, LPT 3BC) — не емулюються
F400:03D4  00              db     00h                         ; Порт 3D4 (CGA 6845: індексний регістр) → nmi_port_3D4, №0
F400:03D5  02              db     02h                         ; Порт 3D5 (CGA 6845: регістр даних) → nmi_port_3D5, №1
F400:03D6  52              db     2 dup (52h)                 ; Порти 3D6–3D7 — не емулюються
F400:03D8  04              db     04h                         ; Порт 3D8 (CGA: регістр режиму) → nmi_port_3D8, №2
F400:03D9  06              db     06h                         ; Порт 3D9 (CGA: регістр вибору кольору/палітри) → nmi_port_3D9, №3
F400:03DA  08              db     08h                         ; Порт 3DA (CGA: регістр стану, зворотний хід) → nmi_port_3DA, №4
F400:03DB  52              db     23 dup (52h)                ; Порти 3DB–3F1 — не емулюються
F400:03F2  3A              db     3Ah                         ; Порт 3F2 (FDC: цифровий вихідний регістр DOR) → nmi_port_3F2, №29
F400:03F3  52              db     1 dup (52h)                 ; Порт 3F3 — не емулюється
F400:03F4  3C              db     3Ch                         ; Порт 3F4 (FDC 765: основний регістр стану MSR) → nmi_port_3F4, №30
F400:03F5  3E              db     3Eh                         ; Порт 3F5 (FDC 765: регістр даних) → nmi_port_3F5, №31
F400:03F6  52              db     2 dup (52h)                 ; Порти 3F6–3F7 — не емулюються
F400:03F8  40              db     40h                         ; Порт 3F8 (COM1 8250: RBR/THR або DLL) → nmi_port_3F8, №32
F400:03F9  42              db     42h                         ; Порт 3F9 (COM1 8250: IER або DLM) → nmi_port_3F9, №33
F400:03FA  44              db     44h                         ; Порт 3FA (COM1 8250: IIR) → nmi_port_3FA, №34
F400:03FB  46              db     46h                         ; Порт 3FB (COM1 8250: LCR) → nmi_port_3FB, №35
F400:03FC  48              db     48h                         ; Порт 3FC (COM1 8250: MCR) → nmi_port_3FC, №36
F400:03FD  4A              db     4Ah                         ; Порт 3FD (COM1 8250: LSR) → nmi_port_3FD, №37
F400:03FE  4C              db     4Ch                         ; Порт 3FE (COM1 8250: MSR) → nmi_port_3FE, №38
F400:03FF  4E              db     4Eh                         ; Порт 3FF (COM1 8250: SCR) → nmi_port_3FF, №39

; ----------------------------------------------------------------------------------------------
; INT0F_IRQ_DISPATCH — спільний обробник апаратних переривань (вектор INT 0Fh), замінює 8259.
; Читає регістр запитів F000:0200 (старший байт): біт 15 — дисковод (INT 0Eh), біт 14 — таймер (INT 08h),
; біт 13 — клавіатура (INT 09h), біт 12 — COM1 (INT 0Ch). За один вхід обслуговується одне джерело за пріоритетом.
; Особливий випадок: IRQ дисковода під час програмної передачі даних FDC (0040:00B9 біт 3 = 0) — стек
; зрізається до адреси повернення в NMI_HANDLER, тобто переривається цикл передачі в nmi_port_3F5.
; ----------------------------------------------------------------------------------------------
INT0F_IRQ_DISPATCH:
F400:0400  06              push   es                          ; Зберігаємо ES перерваної програми
F400:0401  1E              push   ds                          ; Зберігаємо DS
F400:0402  50              push   ax                          ; Зберігаємо AX
F400:0403  FC              cld                                ; Скидання прапорця напрямку для рядкових операцій
F400:0404  B84000          mov    ax, 40h                     ; Сегмент області даних BIOS 0040h…
F400:0407  8ED8            mov    ds, ax                      ; …у DS
F400:0409  B800F0          mov    ax, 0F000h                  ; Сегмент регістрів апаратури F000h…
F400:040C  8EC0            mov    es, ax                      ; …в ES
F400:040E  26A10002        mov    ax, word es:[200h]          ; AX = регістр стану запитів переривань F000:0200 (AH = біти 15–8)
F400:0412  D0E4            shl    ah, 1                       ; Біт 15 → CF: запит від контролера дисковода?
F400:0414  7316            jae    loc_042C                    ; Немає запиту FDC — перевіряємо наступне джерело
F400:0416  A0B900          mov    al, byte [0B9h]             ; AL = 0040:00B9 — тіньова копія регістра керування дисководом F000:0601 (DOR)
