F400:0915  020706070000…   db     02h,07h,06h,07h,00h,00h,00h,00h ; R8=2, R9=7 (символ 8 рядків); курсор 6–7, адреси початку/курсора 0
F400:091D  3F2831047F06…   db     3Fh,28h,31h,04h,7Fh,06h,64h,70h ; графіка 320x200 / 640x200: R0=3Fh, R1=28h, R2=31h, R3=4, R4=7Fh, R5=6, R6=64h(100), R7=70h
F400:0925  020106070000…   db     02h,01h,06h,07h,00h,00h,00h,00h ; R8=2, R9=1 (2 растрові рядки на «символ»); R10–R15 не використовуються
