; ----------------------------------------------------------------------------------------------
; Початок основного 8-КБ блока BIOS (F000:E000). Сигнатура, рядки повідомлень POST (CP866)
; ----------------------------------------------------------------------------------------------
F000:E000  42696F73        db     'Bios'                      ; сигнатура «Bios» на початку блока (входить у контрольну суму E000–FFFF)

; ----------------------------------------------------------------------------------------------
; dat_E004 — заставка, виводиться під час старту (F000:E228 через sub_E6AE)
; ----------------------------------------------------------------------------------------------
dat_E004:    ; посилання: E228
F000:E004  42494F532043…   db     'BIOS Computer & Soft Technol. 1992' ; «BIOS Computer & Soft Technol. 1992» — копірайт фірми-доробника
F000:E026  0A0D            db     0Ah,0Dh                     ; переведення рядка LF, CR
F000:E028  8FAEA4AEA6A4…   db     'Подождите пожалуйста...'   ; «Подождите пожалуйста...» («Зачекайте, будь ласка...») — триває тест пам'яті
F000:E03F  0A0D00          db     0Ah,0Dh,00h                 ; LF, CR, кінець рядка (0)

; ----------------------------------------------------------------------------------------------
; dat_E042 — суфікс лічильника перевіреної пам'яті (виводиться в E34D)
; ----------------------------------------------------------------------------------------------
dat_E042:    ; посилання: E34D
F000:E042  208AA120AFE0…   db     ' Кб проверено'             ; « Кб проверено» (« Кб перевірено») — після числа кілобайтів
F000:E04F  0D00            db     0Dh,00h                     ; CR (курсор на початок рядка для оновлення лічильника), кінець рядка

; ----------------------------------------------------------------------------------------------
; dat_E051 — повідомлення про помилку контрольної суми ПЗП розширення (sub_E46C, E473)
; ----------------------------------------------------------------------------------------------
dat_E051:    ; посилання: E473
F000:E051  208A91208F8793  db     ' КС ПЗУ'                   ; « КС ПЗУ» (« КС ПЗП») — «контрольна сума ПЗП» (неправильна)
F000:E058  0A0D00          db     0Ah,0Dh,00h                 ; LF, CR, кінець рядка

; ----------------------------------------------------------------------------------------------
; RESET — точка входу після скидання (перехід з F000:FFF0, стандартна адреса IBM E05B).
; Якщо за адресою F600:0000 є сигнатура AA55h (ймовірно, зовнішнє ПЗП розширення/альтернативний
; завантажувач) — керування передається йому на F600:0003. Інакше — тест процесора і POST.
; ----------------------------------------------------------------------------------------------
RESET:    ; посилання: EA2E FFF0
F000:E05B  FA              cli                                ; забороняємо масковані переривання
F000:E05C  B800F6          mov    ax, 0F600h                  ; сегмент F600h (фіз. F6000)
F000:E05F  8ED8            mov    ds, ax                      ; DS = F600
F000:E061  813E000055AA    cmp    word [0], 0AA55h            ; є сигнатура ПЗП розширення 55h,AAh?
F000:E067  7509            jne    loc_E072                    ; ні → звичайний POST
F000:E069  EA030000F6      jmp far 0F600h:3                   ; так → передаємо керування ПЗП розширення на F600:0003

; ----------------------------------------------------------------------------------------------
; Адреси повернення для виклику підпрограм без стека (прийом mov sp,адреса + jmp)
; ----------------------------------------------------------------------------------------------
spret_E06E:    ; посилання: E0DE
F000:E06E  E4E0            dw     loc_E0E4                    ; адреса повернення E0E4 після обчислення КС ПЗП (sp=E06E, jmp E62C)

spret_E070:    ; посилання: E127
F000:E070  2DE1            dw     loc_E12D                    ; адреса повернення E12D після тесту перших 16 КБ ОЗП (sp=E070, jmp E447)

; ----------------------------------------------------------------------------------------------
; Тест процесора 8088/8086 (як в IBM PC): перевірка прапорців SF,ZF,AF,PF,CF,OF і
; умовних переходів. За будь-якої помилки — зависання в E0C3.
; ----------------------------------------------------------------------------------------------
loc_E072:    ; посилання: E067
F000:E072  B4D5            mov    ah, 0D5h                    ; AH = D5h: SF, ZF, AF, PF, CF = 1
F000:E074  9E              sahf                               ; завантажуємо у прапорці
F000:E075  734C            jae    loc_E0C3                    ; CF має бути 1
F000:E077  754A            jne    loc_E0C3                    ; ZF має бути 1
F000:E079  7B48            jnp    loc_E0C3                    ; PF має бути 1
F000:E07B  7946            jns    loc_E0C3                    ; SF має бути 1
F000:E07D  9F              lahf                               ; читаємо прапорці назад в AH
F000:E07E  B105            mov    cl, 5                       ; зсув на 5
F000:E080  D2EC            shr    ah, cl                      ; біт 4 (AF) → CF
F000:E082  733F            jae    loc_E0C3                    ; AF має бути 1
F000:E084  B040            mov    al, 40h                     ; AL = 40h
F000:E086  D0E0            shl    al, 1                       ; 40h<<1 = 80h → переповнення, OF=1
F000:E088  7139            jno    loc_E0C3                    ; OF має бути 1
F000:E08A  32E4            xor    ah, ah                      ; AH = 0
F000:E08C  9E              sahf                               ; скидаємо всі прапорці
F000:E08D  7634            jbe    loc_E0C3                    ; CF і ZF мають бути 0
F000:E08F  7832            js     loc_E0C3                    ; SF має бути 0
F000:E091  7A30            jp     loc_E0C3                    ; PF має бути 0
F000:E093  9F              lahf                               ; прапорці → AH
F000:E094  B105            mov    cl, 5                       ; зсув на 5
F000:E096  D2EC            shr    ah, cl                      ; AF → CF
F000:E098  7229            jb     loc_E0C3                    ; AF має бути 0
F000:E09A  D0E4            shl    ah, 1                       ; зсув нуля — OF=0
F000:E09C  7025            jo     loc_E0C3                    ; OF має бути 0

; ----------------------------------------------------------------------------------------------
; Тест регістрів: значення FFFFh, потім 0000h проганяється через усі сегментні й загальні регістри
; ----------------------------------------------------------------------------------------------
F000:E09E  B8FFFF          mov    ax, 0FFFFh                  ; перший прохід — шаблон FFFFh
F000:E0A1  F9              stc                                ; CF=1 — ознака першого проходу

loc_E0A2:    ; посилання: E0BD
F000:E0A2  8ED8            mov    ds, ax                      ; AX → DS
F000:E0A4  8CDB            mov    bx, ds                      ; DS → BX
F000:E0A6  8EC3            mov    es, bx                      ; BX → ES
F000:E0A8  8CC1            mov    cx, es                      ; ES → CX
F000:E0AA  8ED1            mov    ss, cx                      ; CX → SS
F000:E0AC  8CD2            mov    dx, ss                      ; SS → DX
F000:E0AE  8BE2            mov    sp, dx                      ; DX → SP
F000:E0B0  8BEC            mov    bp, sp                      ; SP → BP
F000:E0B2  8BF5            mov    si, bp                      ; BP → SI
F000:E0B4  8BFE            mov    di, si                      ; SI → DI
F000:E0B6  7307            jae    loc_E0BF                    ; другий прохід (CF=0) → перевірка нуля
F000:E0B8  33C7            xor    ax, di                      ; перший прохід: DI має збігтися з FFFFh (AX стане 0)
F000:E0BA  7507            jne    loc_E0C3                    ; не збіглося → помилка процесора
F000:E0BC  F8              clc                                ; CF=0 — другий прохід
F000:E0BD  EBE3            jmp    loc_E0A2                    ; повторюємо з AX = 0

loc_E0BF:    ; посилання: E0B6
F000:E0BF  0BC7            or     ax, di                      ; другий прохід: DI має бути 0
F000:E0C1  7402            je     loc_E0C5                    ; усе правильно → продовження POST

; ----------------------------------------------------------------------------------------------
; Зупинка за фатальної помилки процесора/ПЗП/ОЗП (нескінченний цикл)
; ----------------------------------------------------------------------------------------------
loc_E0C3:    ; посилання: E075 E077 E079 E07B E082 E088 E08D E08F E091 E098 E09C E0BA E0C3 E0E4
F000:E0C3  EBFE            jmp    loc_E0C3                    ; зависання: помилка тесту

; ----------------------------------------------------------------------------------------------
; Початкова ініціалізація апаратури (DS=SS=F000 → запис у регістри F000:0xxx):
; відеорегістр, контролер дисководів, справжній 8255 (F000:0001/3/5/7), потім КС ПЗП.
; ----------------------------------------------------------------------------------------------
loc_E0C5:    ; посилання: E0C1
F000:E0C5  8CCB            mov    bx, cs                      ; BX = CS = F000
F000:E0C7  8ED3            mov    ss, bx                      ; SS = F000 (стек «у ПЗП» для прийому mov sp+jmp)
F000:E0C9  8EDB            mov    ds, bx                      ; DS = F000 — доступ до регістрів апаратури F000:0000–0FFF
F000:E0CB  A30002          mov    word [200h], ax             ; F000:0200 ← 0: відеорегістри (колір/режим) обнулено
F000:E0CE  A20106          mov    byte [601h], al             ; F000:0601 ← 0: регістр керування дисководами — мотори вимк., 765 у скиданні
F000:E0D1  C606070099      mov    byte [7], 99h               ; F000:0007 — керувальне слово справжнього 8255: 99h (PA вхід, PB вихід, PC вхід), як у XT
