; ----------------------------------------------------------------------------------------------
; INT1A_TIME — INT 1Ah (точка IBM F000:FE6E): системний годинник-лічильник тактів.
; AH=0: CX:DX = 0040:006E:006C, AL = прапорець переходу через північ 0040:0070 (скидається);
; AH=1: встановити лічильник з CX:DX. Інші функції ігноруються.
; ----------------------------------------------------------------------------------------------
INT1A_TIME:
F000:FE6E  FB              sti                                ; дозволяємо переривання
F000:FE6F  1E              push   ds                          ; зберігаємо DS
F000:FE70  E87600          call   sub_FEE9                    ; DS = 0040h
F000:FE73  0AE4            or     ah, ah                      ; AH = 0 — читання часу?
F000:FE75  7407            je     loc_FE7E                    ; так
F000:FE77  FECC            dec    ah                          ; AH = 1 — встановлення часу?
F000:FE79  7416            je     loc_FE91                    ; так

loc_FE7B:    ; посилання: FE8F FE9F
F000:FE7B  FB              sti                                ; дозволяємо переривання
F000:FE7C  1F              pop    ds                          ; відновлюємо DS
F000:FE7D  CF              iret                               ; повернення

loc_FE7E:    ; посилання: FE75
F000:FE7E  FA              cli                                ; забороняємо переривання для атомарного читання лічильника
F000:FE7F  A07000          mov    al, byte [70h]              ; AL = 0040:0070 — прапорець «минула доба»
F000:FE82  C606700000      mov    byte [70h], 0               ; скидаємо прапорець доби
F000:FE87  8B0E6E00        mov    cx, word [6Eh]              ; CX = 0040:006E — старше слово лічильника тактів
F000:FE8B  8B166C00        mov    dx, word [6Ch]              ; DX = 0040:006C — молодше слово лічильника тактів
F000:FE8F  EBEA            jmp    loc_FE7B                    ; на вихід

loc_FE91:    ; посилання: FE79
F000:FE91  FA              cli                                ; забороняємо переривання
F000:FE92  89166C00        mov    word [6Ch], dx              ; 0040:006C = DX (мол. слово)
F000:FE96  890E6E00        mov    word [6Eh], cx              ; 0040:006E = CX (ст. слово)
F000:FE9A  C606700000      mov    byte [70h], 0               ; скидаємо прапорець доби 0040:0070
F000:FE9F  EBDA            jmp    loc_FE7B                    ; на вихід

; ----------------------------------------------------------------------------------------------
; dat_FEA1 — обробник-заглушка «mov ah,1 / iret»: ним POST (F000:E192) заповнює всі вектори
; переривань перед встановленням справжніх; непідтримуване переривання поверне AH=1.
; ----------------------------------------------------------------------------------------------
dat_FEA1:    ; посилання: E192
F000:FEA1  B401CF00        db     0B4h,01h,0CFh,00h           ; код: B4 01 = mov ah,1 ; CF = iret ; 00 — вирівнювання

; ----------------------------------------------------------------------------------------------
; INT08_TIMER — INT 08h (точка IBM F000:FEA5), викликається зі спільного обробника F400:0400
; за бітом 14 F000:0200. Лічильник тактів 0040:006C/6E, скидання через добу (1800B0h тактів),
; тайм-аут вимкнення мотора дисковода 0040:0040, виклик користувацького INT 1Ch.
; EOI не надсилається — 8259 немає.
; ----------------------------------------------------------------------------------------------
INT08_TIMER:
F000:FEA5  FB              sti                                ; дозволяємо переривання
F000:FEA6  1E              push   ds                          ; зберігаємо DS
F000:FEA7  50              push   ax                          ; зберігаємо AX
F000:FEA8  52              push   dx                          ; зберігаємо DX
F000:FEA9  E83D00          call   sub_FEE9                    ; DS = 0040h
F000:FEAC  FF066C00        inc    word [6Ch]                  ; інкремент мол. слова лічильника тактів 0040:006C
F000:FEB0  7504            jne    loc_FEB6                    ; без перенесення — далі
F000:FEB2  FF066E00        inc    word [6Eh]                  ; перенесення в ст. слово 0040:006E

loc_FEB6:    ; посилання: FEB0
F000:FEB6  833E6E0018      cmp    word [6Eh], 18h             ; ст. слово = 18h? (доба = 1800B0h тактів по 18,2 Гц)
F000:FEBB  7515            jne    loc_FED2                    ; ні — не північ
F000:FEBD  813E6C00B000    cmp    word [6Ch], 0B0h            ; мол. слово = 0B0h?
F000:FEC3  750D            jne    loc_FED2                    ; ні
F000:FEC5  2BC0            sub    ax, ax                      ; AX = 0
F000:FEC7  A36E00          mov    word [6Eh], ax              ; обнуляємо ст. слово лічильника
F000:FECA  A36C00          mov    word [6Ch], ax              ; обнуляємо мол. слово лічильника
F000:FECD  C606700001      mov    byte [70h], 1               ; 0040:0070 = 1 — прапорець переходу через північ

loc_FED2:    ; посилання: FEBB FEC3
F000:FED2  FE0E4000        dec    byte [40h]                  ; 0040:0040 — лічильник тактів до вимкнення мотора дисковода
F000:FED6  750B            jne    loc_FEE3                    ; ще не минув
F000:FED8  80263F00F0      and    byte [3Fh], 0F0h            ; 0040:003F — скидаємо біти «мотор увімкнено» дисководів 0–3
F000:FEDD  B00C            mov    al, 0Ch                     ; DOR = 0Ch: DMA/IRQ дозволено, контролер не в скиданні, мотори вимк.
F000:FEDF  BAF203          mov    dx, 3F2h                    ; порт 3F2h — регістр цифрового виведення FDC (емулюється через NMI)
F000:FEE2  EE              out    dx, al                      ; вимикаємо мотори дисководів

loc_FEE3:    ; посилання: FED6
F000:FEE3  CD1C            int    1Ch                         ; виклик користувацького обробника такту INT 1Ch
F000:FEE5  5A              pop    dx                          ; відновлюємо DX
F000:FEE6  58              pop    ax                          ; відновлюємо AX
F000:FEE7  1F              pop    ds                          ; відновлюємо DS
F000:FEE8  CF              iret                               ; повернення (без EOI — контролера переривань немає)

; ----------------------------------------------------------------------------------------------
; sub_FEE9 — DS = 0040h (сегмент області даних BIOS). AX зберігається.
; ----------------------------------------------------------------------------------------------
sub_FEE9:    ; посилання: E268 E2D8 E746 E831 E914 EC63 EF5A EFD8 F080 F2A9 F71A F843 F84F F872 FE70 FEA9
F000:FEE9  50              push   ax                          ; зберігаємо AX
F000:FEEA  B84000          mov    ax, 40h                     ; AX = 0040h
F000:FEED  8ED8            mov    ds, ax                      ; DS = сегмент області даних BIOS
F000:FEEF  58              pop    ax                          ; відновлюємо AX
F000:FEF0  C3              ret                                ; повернення
F000:FEF1  0000            db     00h,00h                     ; заповнювач до таблиці векторів F000:FEF3

