; ----------------------------------------------------------------------------------------------
keypad_table:    ; посилання: EB77
F000:FF23  3738392D3435…   db     '789-456+1230.'             ; скан 47h–53h: 7 8 9 - 4 5 6 + 1 2 3 0 .

; ----------------------------------------------------------------------------------------------
; dat_FF30 — розширені коди (в AH, AL=0) цифрової клавіатури без NumLock (Home, ↑, PgUp, ←, →, End...).
; Індекс = скан-47h; FFh — клавіша без розширеного коду (центральна 5 тощо).
; ----------------------------------------------------------------------------------------------
dat_FF30:    ; посилання: EB5E
F000:FF30  474849FF4BFF…   db     47h,48h,49h,0FFh,4Bh,0FFh,4Dh,0FFh ; скан 47h Home, 48h ↑, 49h PgUp, 4Ah (сірий -) FFh, 4Bh ←, 4Ch (5) FFh, 4Dh →, 4Eh (сірий +) FFh
F000:FF38  4F50515253      db     'OPQRS'                     ; скан 4Fh End, 50h ↓, 51h PgDn, 52h Ins, 53h Del — розширені коди = скан-кодам

; ----------------------------------------------------------------------------------------------
; loc_FF3D — завершення налаштування DMA для INT 13h (продовження sub_F73E, перехід з F000:F770).
; Вхід: AX = (кількість секторів)·128, CL = код розміру сектора N (байт 3 таблиці параметрів дисковода);
; у стеку адреса буфера і CX викликача. Програмує лічильник каналу 2 8237 (порт 05h, емулюється),
; знімає маску каналу 2 (порт 0Ah). Вихід: CF = 1 — буфер перетинає межу 64 КБ.
; ----------------------------------------------------------------------------------------------
loc_FF3D:    ; посилання: F770
F000:FF3D  D3E0            shl    ax, cl                      ; AX = довжина передавання в байтах = сектори·128·2^N
F000:FF3F  48              dec    ax                          ; 8237 програмується довжиною-1
F000:FF40  50              push   ax                          ; зберігаємо довжину-1
F000:FF41  E605            out    5, al                       ; мол. байт лічильника каналу 2 DMA (порт 05h)
F000:FF43  8AC4            mov    al, ah                      ; AL = ст. байт довжини-1
F000:FF45  E605            out    5, al                       ; ст. байт лічильника каналу 2 DMA (порт 05h)
F000:FF47  59              pop    cx                          ; CX = довжина-1
F000:FF48  58              pop    ax                          ; AX = 16-бітна адреса буфера (збережена в F753)
F000:FF49  03C1            add    ax, cx                      ; адреса+довжина-1: CF=1 при переході через межу 64 КБ (помилка DMA)
F000:FF4B  59              pop    cx                          ; відновлюємо CX викликача (push у F73E)
F000:FF4C  B002            mov    al, 2                       ; команда маски: зняти маску каналу 2 (дисковод)
F000:FF4E  E60A            out    0Ah, al                     ; порт 0Ah — регістр одиночної маски 8237 (емулюється); прапорці не змінюються
F000:FF50  C3              ret                                ; повернення з CF = ознака перетину межі 64 КБ
F000:FF51  0000            db     00h,00h                     ; заповнювач до F000:FF53

; ----------------------------------------------------------------------------------------------
; DUMMY_IRET — порожній обробник переривань (стандартна адреса IBM F000:FF53).
; ----------------------------------------------------------------------------------------------
DUMMY_IRET:
F000:FF53  CF              iret                               ; негайне повернення з переривання

; ----------------------------------------------------------------------------------------------
; INT05_PRTSCR — INT 05h (точка IBM F000:FF54): друк копії екрана на принтер (INT 17h, LPT1).
; Статус у 0050:0000: 1 — триває друк, 0 — успішно, FFh — помилка.
; Символи читаються через INT 10h AH=8 (25 рядків × кількість колонок), курсор відновлюється.
; ----------------------------------------------------------------------------------------------
INT05_PRTSCR:
F000:FF54  FB              sti                                ; дозволяємо переривання
F000:FF55  1E              push   ds                          ; зберігаємо DS
F000:FF56  50              push   ax                          ; зберігаємо AX
F000:FF57  53              push   bx                          ; зберігаємо BX
F000:FF58  51              push   cx                          ; зберігаємо CX
F000:FF59  52              push   dx                          ; зберігаємо DX
F000:FF5A  B85000          mov    ax, 50h                     ; AX = 0050h
F000:FF5D  8ED8            mov    ds, ax                      ; DS = 0050h (байт статусу друку екрана 0050:0000)
F000:FF5F  803E000001      cmp    byte [0], 1                 ; друк екрана вже виконується?
F000:FF64  745F            je     loc_FFC5                    ; так — повторний вхід заборонено, вихід
F000:FF66  C606000001      mov    byte [0], 1                 ; статус = 1 — триває друк
F000:FF6B  B40F            mov    ah, 0Fh                     ; INT 10h AH=0Fh — отримати відеорежим
F000:FF6D  CD10            int    10h                         ; AH = кількість колонок, BH = активна сторінка
F000:FF6F  8ACC            mov    cl, ah                      ; CL = кількість колонок
F000:FF71  B519            mov    ch, 19h                     ; CH = 25 рядків
F000:FF73  E85500          call   sub_FFCB                    ; переведення рядка на принтері перед копією
F000:FF76  51              push   cx                          ; зберігаємо розміри екрана
F000:FF77  B403            mov    ah, 3                       ; INT 10h AH=3 — прочитати позицію курсора
F000:FF79  CD10            int    10h                         ; DX = поточна позиція курсора
F000:FF7B  59              pop    cx                          ; відновлюємо CX (розміри)
F000:FF7C  52              push   dx                          ; зберігаємо позицію курсора для відновлення
F000:FF7D  33D2            xor    dx, dx                      ; починаємо з позиції (0,0)

loc_FF7F:    ; посилання: FF9E FFAD
F000:FF7F  B402            mov    ah, 2                       ; INT 10h AH=2 — встановити курсор у DH:DL
F000:FF81  CD10            int    10h                         ; ставимо курсор
F000:FF83  B408            mov    ah, 8                       ; INT 10h AH=8 — прочитати символ/атрибут під курсором
F000:FF85  CD10            int    10h                         ; AL = символ (у графіці програмного малювання — розпізнається за шрифтом)
F000:FF87  0AC0            or     al, al                      ; символ 0 (не розпізнано)?
F000:FF89  7502            jne    loc_FF8D                    ; ні — друкуємо як є
F000:FF8B  B020            mov    al, 20h                     ; 0 замінюємо пробілом

loc_FF8D:    ; посилання: FF89
F000:FF8D  52              push   dx                          ; зберігаємо позицію
F000:FF8E  33D2            xor    dx, dx                      ; DX = 0 — принтер LPT1
F000:FF90  32E4            xor    ah, ah                      ; INT 17h AH=0 — друк символу
F000:FF92  CD17            int    17h                         ; друкуємо символ AL
F000:FF94  5A              pop    dx                          ; відновлюємо позицію
F000:FF95  F6C425          test   ah, 25h                     ; статус принтера: біт 0 тайм-аут, біт 2 (резерв), біт 5 немає паперу
F000:FF98  7521            jne    loc_FFBB                    ; помилка принтера — аварійний вихід
F000:FF9A  FEC2            inc    dl                          ; наступна колонка
F000:FF9C  3ACA            cmp    cl, dl                      ; кінець рядка?
F000:FF9E  75DF            jne    loc_FF7F                    ; ні — наступний символ
F000:FFA0  32D2            xor    dl, dl                      ; колонка 0
F000:FFA2  8AE2            mov    ah, dl                      ; AH = 0 (ймовірно, зайва команда — sub_FFCB однаково затирає AX)
F000:FFA4  52              push   dx                          ; зберігаємо позицію
F000:FFA5  E82300          call   sub_FFCB                    ; переведення рядка на принтері
F000:FFA8  5A              pop    dx                          ; відновлюємо позицію
F000:FFA9  FEC6            inc    dh                          ; наступний рядок екрана
F000:FFAB  3AEE            cmp    ch, dh                      ; усі 25 рядків?
F000:FFAD  75D0            jne    loc_FF7F                    ; ні — продовжуємо
F000:FFAF  5A              pop    dx                          ; DX = початкова позиція курсора
F000:FFB0  B402            mov    ah, 2                       ; INT 10h AH=2
F000:FFB2  CD10            int    10h                         ; відновлюємо курсор
F000:FFB4  C606000000      mov    byte [0], 0                 ; статус 0 — друк успішно завершено
F000:FFB9  EB0A            jmp    loc_FFC5                    ; на вихід

loc_FFBB:    ; посилання: FF98
F000:FFBB  5A              pop    dx                          ; DX = початкова позиція курсора
F000:FFBC  B402            mov    ah, 2                       ; INT 10h AH=2
F000:FFBE  CD10            int    10h                         ; відновлюємо курсор
F000:FFC0  C6060000FF      mov    byte [0], 0FFh              ; статус FFh — помилка друку

loc_FFC5:    ; посилання: FF64 FFB9
F000:FFC5  5A              pop    dx                          ; відновлюємо DX
F000:FFC6  59              pop    cx                          ; відновлюємо CX
F000:FFC7  5B              pop    bx                          ; відновлюємо BX
F000:FFC8  58              pop    ax                          ; відновлюємо AX
F000:FFC9  1F              pop    ds                          ; відновлюємо DS
F000:FFCA  CF              iret                               ; повернення з переривання

; ----------------------------------------------------------------------------------------------
; sub_FFCB — переведення рядка на принтері LPT1: виводить LF (0Ah), потім CR (0Dh) через INT 17h
; (CR друкує хвіст F000:E97E, який і робить ret). Псує AX, DX=0.
; ----------------------------------------------------------------------------------------------
sub_FFCB:    ; посилання: FF73 FFA5
F000:FFCB  33D2            xor    dx, dx                      ; DX = 0 — принтер LPT1
F000:FFCD  B80A00          mov    ax, 0Ah                     ; AH = 0 (друк), AL = 0Ah — LF
F000:FFD0  CD17            int    17h                         ; друкуємо LF
F000:FFD2  E9A9E9          jmp    loc_E97E                    ; хвіст у E97E: друк CR (0Dh) і ret

; ----------------------------------------------------------------------------------------------
; sub_FFD5 — опитування клавіатури під час роботи зі стрічкою.
; Читає скан-код з F000:0001 (порт A 8255, аналог 60h) і квитує клавіатуру імпульсом
; бітів 7 і 5 у F000:0003 (порт B 8255; біт 5 — зняття запиту переривання клавіатури, пор. F400:043E).
; Вихід: AL = скан-код, ZF = 1, якщо натиснуто Esc (скан 01h).
; ----------------------------------------------------------------------------------------------
sub_FFD5:    ; посилання: F8BF F8E1 F91E
F000:FFD5  2EA00100        mov    al, byte cs:[1]             ; AL = скан-код з F000:0001 (порт A 8255)
F000:FFD9  50              push   ax                          ; зберігаємо скан-код
F000:FFDA  2EA00300        mov    al, byte cs:[3]             ; AL = поточне значення F000:0003 (порт B 8255)
F000:FFDE  8AE0            mov    ah, al                      ; AH = початкове значення порту B
F000:FFE0  0CA0            or     al, 0A0h                    ; біти 7 (скидання клавіатури) і 5 (зняття запиту переривання) = 1
F000:FFE2  2EA20300        mov    byte cs:[3], al             ; виставляємо імпульс квитування
F000:FFE6  2E88260300      mov    byte cs:[3], ah             ; повертаємо початкове значення порту B
F000:FFEB  58              pop    ax                          ; AL = скан-код
F000:FFEC  3C01            cmp    al, 1                       ; Esc (скан 01h)? → ZF
F000:FFEE  C3              ret                                ; повернення
F000:FFEF  00              db     00h                         ; заповнювач до вектора скидання F000:FFF0

; ----------------------------------------------------------------------------------------------
; POWER_ON — вектор скидання процесора (FFFF:0000 = F000:FFF0): перехід на RESET F000:E05B.
; За ним дата версії ПЗП і байт типу моделі.
; ----------------------------------------------------------------------------------------------
POWER_ON:
F000:FFF0  EA5BE000F0      jmp    far RESET                   ; далекий перехід на початок POST F000:E05B
F000:FFF5  30312F30312F…   db     '01/01/91'                  ; дата ПЗП «01/01/91» (стандартне місце IBM F000:FFF5)
F000:FFFD  00FFCD          db     00h,0FFh,0CDh               ; 00h; FFh — ідентифікатор моделі (як IBM PC); CDh — ймовірно, байт вирівнювання контрольної суми
